configuration.expression:
// Regelguete-Bins (ThingsBoard Script Calculated Field, TBEL)
// Drei sich ausschliessende Zustaende (Summe immer 1):
//   binUnregulated = 1 : kein Speicher aktiv
//   binSaturated   = 1 : mind. ein Speicher an der Leistungsgrenze
//   binRegulated   = 1 : aktiv und beide innerhalb der Grenze
// Nur bei binRegulated gibt es die 5 Abweichungs-Bins und qualityScore,
// damit dessen Tagesdurchschnitt nur bewertbare Zeiten enthaelt.
//
// Hinweis TBEL: in Map-Literalen keine "a ? b : c"-Ausdruecke.
// Eingaenge koennen als Zahl, String oder leer ankommen. Leere bzw.
// nicht verfuegbare Werte gelten als fehlend (0 W bei den Speichern,
// "nicht geregelt" bei gridPower).

function leer(v) {
  if (v == null) { return true; }
  var s = ("" + v).trim();
  return s == "" || s == "null" || s == "unavailable" || s == "unknown";
}

function num(v) {
  if (leer(v)) { return 0; }
  return parseDouble(("" + v).trim());
}

var TOL    = 15;   // W: Toleranzband um 0
var GROSS  = 50;   // W: Grenze kleine/grosse Abweichung
var AKTIV  = 5;    // W: ab hier gilt ein Speicher als aktiv

// Nur einmal pro Minute auswerten: erst wenn der Netzwert der neueste
// ist (die Bridge sendet das Netz-Geraet als letztes). Die Laeufe, die
// von den Speicher-Nachrichten ausgeloest werden, liefern nichts.
var tNetz = 0;
if (ctx.args.gridPower != null) { tNetz = ctx.args.gridPower.ts; }
var tMax = 0;
if (ctx.args.sf2400home != null && ctx.args.sf2400home.ts > tMax) { tMax = ctx.args.sf2400home.ts; }
if (ctx.args.sf2400charge != null && ctx.args.sf2400charge.ts > tMax) { tMax = ctx.args.sf2400charge.ts; }
if (ctx.args.sf800home != null && ctx.args.sf800home.ts > tMax) { tMax = ctx.args.sf800home.ts; }
if (ctx.args.sf800charge != null && ctx.args.sf800charge.ts > tMax) { tMax = ctx.args.sf800charge.ts; }
if (tNetz < tMax) {
  return {};
}

var GRENZE_2400 = 790; // W: Saettigung SF2400 - an dein Geraet anpassen
var GRENZE_800  = 790;  // W: Saettigung SF800

var p  = num(gridPower);
var a1 = num(sf2400home) + num(sf2400charge);
var a2 = num(sf800home)  + num(sf800charge);

var aktiv = 0;
if (a1 > AKTIV || a2 > AKTIV) { aktiv = 1; }

var satt = 0;
if (a1 > GRENZE_2400 || a2 > GRENZE_800) { satt = 1; }

// 1) Nicht geregelt (oder keine Netzmessung)
if (leer(gridPower) || aktiv == 0) {
  var aus = {
    "binRegulated": 0,
    "binSaturated": 0,
    "binUnregulated": 1
  };
  return aus;
}

// 2) An der Leistungsgrenze: nicht bewertbar
if (satt == 1) {
  var sat = {
    "binRegulated": 0,
    "binSaturated": 1,
    "binUnregulated": 0
  };
  return sat;
}

// 3) Bewertbar: klassifizieren
var inTol = 0;
var smallImp = 0;
var largeImp = 0;
var smallExp = 0;
var largeExp = 0;

if (p >= -TOL && p <= TOL) {
  inTol = 1;
} else if (p > TOL && p <= GROSS) {
  smallImp = 1;
} else if (p > GROSS) {
  largeImp = 1;
} else if (p < -TOL && p >= -GROSS) {
  smallExp = 1;
} else {
  largeExp = 1;
}

var q = 0;
if (inTol == 1) { q = 100; }

var res = {
  "binRegulated": 1,
  "binSaturated": 0,
  "binUnregulated": 0,
  "binInTolerance": inTol,
  "binSmallImport": smallImp,
  "binLargeImport": largeImp,
  "binSmallExport": smallExp,
  "binLargeExport": largeExp,
  "qualityScore": q
};
return res;
